To find the nth Newman–Shanks–Williams prime number, you can use a recursive function to generate the sequence and check for primality. Here's a Python function to achieve this:

```python
def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def newman_prime(n):
    """Find the nth Newman–Shanks–Williams prime number."""
    def ns_williams(a, b, k):
        """Generate the k-th Newman–Shanks–Williams number."""
        if k == 0:
            return a
        if k == 1:
            return b
        return ns_williams(a, b, k - 1) * ns_williams(a, b, k - 2) + 1

    count = 0
    a, b = 2, 1
    while True:
        num = ns_williams(a, b, count)
        if is_prime(num):
            count += 1
            if count == n:
                return num

# Test the function with the provided test case
assert newman_prime(3) == 7
```

