def prod_Square(n):
    # n = (i*j)^2 with i, j >= 2, so n must be a perfect square
    # whose square root is composite (excludes trivial factor 1).
    if n < 4:
        return False
    k = int(n ** 0.5)
    while k * k > n:
        k -= 1
    while (k + 1) * (k + 1) <= n:
        k += 1
    if k * k != n:
        return False
    for i in range(2, int(k ** 0.5) + 1):
        if k % i == 0:
            return True
    return False
```

