def find_Element(arr, ranges, rotations, index):
    # Trace the index backwards through the rotations, last to first.
    # Each rotation right-shifts the subarray arr[l..r] by one position.
    for i in range(rotations - 1, -1, -1):
        l, r = ranges[i]
        if l <= index <= r:
            if index == l:
                index = r
            else:
                index -= 1
    return arr[index]
