from typing import List

def find_minimum_range(arrays: List[List[int]]) -> tuple:
    if not arrays:
        return ()

    min_val = min(array[0] for array in arrays)
    max_val = max(array[-1] for array in arrays)

    while min_val < max_val:
        mid = (min_val + max_val) // 2
        if all(any(mid <= num <= mid + 1 for num in array) for array in arrays):
            max_val = mid
        else:
            min_val = mid + 1

    return (min_val, min_val + 1)
