import heapq

def func(sorted_lists, k):
    def count_integers(lst):
        return len([num for num in lst if isinstance(num, int)])

    def heapify(heap, i):
        while True:
            smallest = i
            left = 2 * i + 1
            right = 2 * i + 2

            if left < len(heap) and heap[left] < heap[smallest]:
                smallest = left

            if right < len(heap) and heap[right] < heap[smallest]:
                smallest = right

            if smallest == i:
                break

            heap[i], heap[smallest] = heap[smallest], heap[i]
            i = smallest

    def heap_sort(heap):
        heapq.heapify(heap)
        for _ in range(len(heap) - 1):
            heapq.heappop(heap)
        return heap

    integers = [num for lst in sorted_lists for num in lst]
    integers.sort()

    heap = []
    for num in integers:
        if len(heap) < k:
            heapq.heappush(heap, num)
        else:
            if num < heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, num)

    return [heapq.heappop(heap) for _ in range(k)]
